insert into public.email_automations(id,key,name,trigger_type,is_active) values('22445b31-b0b5-5beb-9bd7-1916852d47e4','course_tantra-mystery','Тантра - мистерия взаимоотношений','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('tantra-mystery','Тантра - мистерия взаимоотношений','practicum','https://zamkovoi.yoga/tantra12',90,3,5,'22445b31-b0b5-5beb-9bd7-1916852d47e4','2a73d00270302eeef8761270a790917ded9c5b20413304925fb408df6b955f6f') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('482c7831-1588-5e08-88f0-69796e977c83','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 1: Знакомство с внутренним мужчиной или женщиной',1,0,'{Тантра} Урок 1 - Знакомство с внутренним мужчиной или женщиной','{"ru":"{Тантра} Урок 1 - Знакомство с внутренним мужчиной или женщиной"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Привет, {{name}}! </p><p></p><p>Я рад, что вы решили пройти курс &quot;Тантра - мистерия взаимоотношений&quot;!</p><p></p><p>Хотя учение тантры, как и йога, базируется на Ведах, и в тантре принята такая-же чакральная модель личности, тантра отличается от йоги (в привычном нам понимании) по своему духу. И чтобы лучше объяснить детали, и быстрей ввести Вас в поток, первый урок я провёл в формате вебинара.</p><p></p><p>А также на странице первого урока находятся ещё два дополнительных урока для работы с телом. Не беспокойтесь, в дальнейших днях курса контента будет не так много.</p><p></p><p>Ссылка на страницу с первым уроком</p><p></p><p><strong>Расписание и доступ к урокам:</strong><br>Этот курс содержит 12 уроков, и проходится за 4 недели. То есть каждую неделю Вы будете получать по три урока. В течение прохождения курса уроки будут открываться друг за другом по расписанию. При этом доступ к пройденным урокам у Вас сохранится в течение трёх месяцев после окончания курса. Тем не менее, я рекомендую Вам просматривать уроки и выполнять задания сразу - в день получения моего письма со ссылкой на урок, чтобы у Вас был ещё день на переваривание знаний перед тем, как придёт следующий урок.</p><p></p><p>И ещё обращаю Ваше внимание на то, что каждый урок является практическим. Если не выполнять практики, то результаты от курса будут мизерные. Надеюсь, это логично и понятно :) Но я предлагаю пойти ещё дальше, и по результатам каждой практики писать краткий отчет, ратифицирующий полученные результаты. Обращаю внимание - это нужно не мне, а Вам. Фиксация результатов в письменном виде способствует их фиксации и в сознании. Для этой цели внизу страницы каждого урока предусмотрено поле для записей.</p><p></p><p><strong>Вебинары и ответы на вопросы:</strong><br>В процессе прохождения уроков у Вас наверняка будут возникать вопросы. Чтобы поддерживать живую обратную связь и отвечать на ваши вопросы, каждую неделю я провожу закрытые групповые консультации (вебинары). Обычно они проходят по субботам. Перед началом каждого вебинара я буду отправлять письмо со ссылкой на вебинарную комнату. То есть у Вас впереди 4 вебинара. Не упускайте эту возможность, чтобы получить от данного курса максимальный эффект!</p><p></p><p><strong>Техника безопасности:</strong><br>Я забочусь о Вашем здоровье и напоминаю, что только Вы несёте ответственность за адекватность выполнения рекомендованных в данном курсе заданий (то есть асан, пранаям и медитаций) Вашим физическим возможностям и психическому состоянию. В случае необходимости, целесообразность выполнения заданий должна согласовываться с врачом. Важно понимать, что это онлайн курс, и я не могу контролировать состояние каждого, кто на него записывается. А люди бывают разные. У каждого есть физические и психологические особенности. Я с любовью отобрал, и предлагаю Вам максимально эффективные техники, необходимые для достижения целей данного курса. Но я не несу ответственности за последствия их применения. Пожалуйста, будьте внимательны к своему состоянию.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть первый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Желаю удачи на пути тантры! <br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Привет, {{name}}! </p><p></p><p>Я рад, что вы решили пройти курс &quot;Тантра - мистерия взаимоотношений&quot;!</p><p></p><p>Хотя учение тантры, как и йога, базируется на Ведах, и в тантре принята такая-же чакральная модель личности, тантра отличается от йоги (в привычном нам понимании) по своему духу. И чтобы лучше объяснить детали, и быстрей ввести Вас в поток, первый урок я провёл в формате вебинара.</p><p></p><p>А также на странице первого урока находятся ещё два дополнительных урока для работы с телом. Не беспокойтесь, в дальнейших днях курса контента будет не так много.</p><p></p><p>Ссылка на страницу с первым уроком</p><p></p><p><strong>Расписание и доступ к урокам:</strong><br>Этот курс содержит 12 уроков, и проходится за 4 недели. То есть каждую неделю Вы будете получать по три урока. В течение прохождения курса уроки будут открываться друг за другом по расписанию. При этом доступ к пройденным урокам у Вас сохранится в течение трёх месяцев после окончания курса. Тем не менее, я рекомендую Вам просматривать уроки и выполнять задания сразу - в день получения моего письма со ссылкой на урок, чтобы у Вас был ещё день на переваривание знаний перед тем, как придёт следующий урок.</p><p></p><p>И ещё обращаю Ваше внимание на то, что каждый урок является практическим. Если не выполнять практики, то результаты от курса будут мизерные. Надеюсь, это логично и понятно :) Но я предлагаю пойти ещё дальше, и по результатам каждой практики писать краткий отчет, ратифицирующий полученные результаты. Обращаю внимание - это нужно не мне, а Вам. Фиксация результатов в письменном виде способствует их фиксации и в сознании. Для этой цели внизу страницы каждого урока предусмотрено поле для записей.</p><p></p><p><strong>Вебинары и ответы на вопросы:</strong><br>В процессе прохождения уроков у Вас наверняка будут возникать вопросы. Чтобы поддерживать живую обратную связь и отвечать на ваши вопросы, каждую неделю я провожу закрытые групповые консультации (вебинары). Обычно они проходят по субботам. Перед началом каждого вебинара я буду отправлять письмо со ссылкой на вебинарную комнату. То есть у Вас впереди 4 вебинара. Не упускайте эту возможность, чтобы получить от данного курса максимальный эффект!</p><p></p><p><strong>Техника безопасности:</strong><br>Я забочусь о Вашем здоровье и напоминаю, что только Вы несёте ответственность за адекватность выполнения рекомендованных в данном курсе заданий (то есть асан, пранаям и медитаций) Вашим физическим возможностям и психическому состоянию. В случае необходимости, целесообразность выполнения заданий должна согласовываться с врачом. Важно понимать, что это онлайн курс, и я не могу контролировать состояние каждого, кто на него записывается. А люди бывают разные. У каждого есть физические и психологические особенности. Я с любовью отобрал, и предлагаю Вам максимально эффективные техники, необходимые для достижения целей данного курса. Но я не несу ответственности за последствия их применения. Пожалуйста, будьте внимательны к своему состоянию.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть первый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Желаю удачи на пути тантры! <br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-01-text","type":"text","html":"<p>Привет, {{name}}! </p><p></p><p>Я рад, что вы решили пройти курс &quot;Тантра - мистерия взаимоотношений&quot;!</p><p></p><p>Хотя учение тантры, как и йога, базируется на Ведах, и в тантре принята такая-же чакральная модель личности, тантра отличается от йоги (в привычном нам понимании) по своему духу. И чтобы лучше объяснить детали, и быстрей ввести Вас в поток, первый урок я провёл в формате вебинара.</p><p></p><p>А также на странице первого урока находятся ещё два дополнительных урока для работы с телом. Не беспокойтесь, в дальнейших днях курса контента будет не так много.</p><p></p><p>Ссылка на страницу с первым уроком</p><p></p><p><strong>Расписание и доступ к урокам:</strong><br>Этот курс содержит 12 уроков, и проходится за 4 недели. То есть каждую неделю Вы будете получать по три урока. В течение прохождения курса уроки будут открываться друг за другом по расписанию. При этом доступ к пройденным урокам у Вас сохранится в течение трёх месяцев после окончания курса. Тем не менее, я рекомендую Вам просматривать уроки и выполнять задания сразу - в день получения моего письма со ссылкой на урок, чтобы у Вас был ещё день на переваривание знаний перед тем, как придёт следующий урок.</p><p></p><p>И ещё обращаю Ваше внимание на то, что каждый урок является практическим. Если не выполнять практики, то результаты от курса будут мизерные. Надеюсь, это логично и понятно :) Но я предлагаю пойти ещё дальше, и по результатам каждой практики писать краткий отчет, ратифицирующий полученные результаты. Обращаю внимание - это нужно не мне, а Вам. Фиксация результатов в письменном виде способствует их фиксации и в сознании. Для этой цели внизу страницы каждого урока предусмотрено поле для записей.</p><p></p><p><strong>Вебинары и ответы на вопросы:</strong><br>В процессе прохождения уроков у Вас наверняка будут возникать вопросы. Чтобы поддерживать живую обратную связь и отвечать на ваши вопросы, каждую неделю я провожу закрытые групповые консультации (вебинары). Обычно они проходят по субботам. Перед началом каждого вебинара я буду отправлять письмо со ссылкой на вебинарную комнату. То есть у Вас впереди 4 вебинара. Не упускайте эту возможность, чтобы получить от данного курса максимальный эффект!</p><p></p><p><strong>Техника безопасности:</strong><br>Я забочусь о Вашем здоровье и напоминаю, что только Вы несёте ответственность за адекватность выполнения рекомендованных в данном курсе заданий (то есть асан, пранаям и медитаций) Вашим физическим возможностям и психическому состоянию. В случае необходимости, целесообразность выполнения заданий должна согласовываться с врачом. Важно понимать, что это онлайн курс, и я не могу контролировать состояние каждого, кто на него записывается. А люди бывают разные. У каждого есть физические и психологические особенности. Я с любовью отобрал, и предлагаю Вам максимально эффективные техники, необходимые для достижения целей данного курса. Но я не несу ответственности за последствия их применения. Пожалуйста, будьте внимательны к своему состоянию.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть первый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Желаю удачи на пути тантры! <br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-01','tantra-mystery',1,0,'Урок 1: Знакомство с внутренним мужчиной или женщиной','[{"type":"text","markdown":"**СОЗНАНИЕ**\nПочему Вас привлекла тантра? Большинство людей над этим вопросом даже не задумываются. Для кого-то тантра - это путь в духовность, для кого-то новый формат взаимодействия с противоположным полом... Вариантов множество. И обычно мотивы остаются неосознанными. Попробуйте ответить себе на этот вопрос. В результате осознанных практик тантры с соответствующим намерением, Ваш прогресс существенно ускорится.\n\nИ сейчас я предлагаю Вам посмотреть урок, в котором рассматривается история возникновения тантры. Вы поймёте почему тантра находится на вершине мистических психотехник буддизма и индуизма. А также мы выполним простейшую асану на растяжку, наполнив её содержанием, превращающим данную асану в ценнейшую тантрическую практику. Отнеситесь к этой практике как к медитации. В будущем вы заметите, что каждый раз она приносит вам новые плоды :)"},{"type":"video","vimeoId":"1108026280"},{"type":"text","markdown":"\n\n**СУСТАВНАЯ ГИМНАСТИКА**\nТак как уровень в йоге у всех разный. Давай начнём с того, что будет полезно всем. Первые дни посвятим суставной гимнастике. Ежедневно выполняйте её по приложенному видео. При этом важны два нюанса:\n- Удерживайте волевое намерение запустить в теле 6-недельную программу растяжки (дайте телу сигнал, чтобы оно приготовилось)\n- В данном видео суставная гимнастика делается на энергии третьей чакры - манипуры (то есть с целью разогреть и активизировать тело). Вы же возьмите энергию второй чакры - свадхистханы. То есть почувствуйте себя водой, тягучей, податливой, мягкой, гибкой. Состояние блаженно идущей по тёплой улице кошки, которая получает удовольствие от каждого движения. Также и вы ощутите удовольствие при сгибании пальцев рук, от тянущих ощущениях в плечах при вращении рук, и т.д. Это очень просто. Нужно всего-лишь направить на эти состояния своё внимание..."},{"type":"video","vimeoId":"1108077416"},{"type":"text","markdown":"\n\n**ПАССИВНАЯ РАСТЯЖКА**\nА также, начиная с сегодняшнего дня, включите в свой распорядок дня на всё время прохождения курса ежедневные упражнения пассивной растяжки:\n- 30 минут вращения тазом\n- 10 минут осознанная походка\n- 10 минут пассивная растяжка за чтением книг или просмотром видеоуроков этого курса"},{"type":"video","vimeoId":"1108077484"}]'::jsonb,'482c7831-1588-5e08-88f0-69796e977c83') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('00895369-c032-54e4-8212-5f41c5aa9a68','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 2: Работа с энергетическим двойником',2,0,'{Тантра} Урок 2 - Работа с энергетическим двойником','{"ru":"{Тантра} Урок 2 - Работа с энергетическим двойником"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Привет, {{name}}! На прошлом уроке мы познакомились с метафорой внутреннего мужчины и внутренней женщины, а также перевели эту метафору на уровень ощущений внутренних состояни. Сегодня мы перейдём на более глубокий уровень. Мы рассмотрим внутреннего партнёра как энергетического двойника, и будем учиться с ним взаимодействовать. А также Вас ожидают асаны йоги.</p><p></p><p>Чтобы глубже раскрыть тему, и сделать знание живым, этот урок я тоже провёл в формате вебинара.</p><p></p><p>Обязательно выполняйте задания каждого урока, чтобы превращать свободно летающую в пространстве информацию в свой личный опыт и знания.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>С пожеланиями открытий, <br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Привет, {{name}}! На прошлом уроке мы познакомились с метафорой внутреннего мужчины и внутренней женщины, а также перевели эту метафору на уровень ощущений внутренних состояни. Сегодня мы перейдём на более глубокий уровень. Мы рассмотрим внутреннего партнёра как энергетического двойника, и будем учиться с ним взаимодействовать. А также Вас ожидают асаны йоги.</p><p></p><p>Чтобы глубже раскрыть тему, и сделать знание живым, этот урок я тоже провёл в формате вебинара.</p><p></p><p>Обязательно выполняйте задания каждого урока, чтобы превращать свободно летающую в пространстве информацию в свой личный опыт и знания.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>С пожеланиями открытий, <br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-02-text","type":"text","html":"<p>Привет, {{name}}! На прошлом уроке мы познакомились с метафорой внутреннего мужчины и внутренней женщины, а также перевели эту метафору на уровень ощущений внутренних состояни. Сегодня мы перейдём на более глубокий уровень. Мы рассмотрим внутреннего партнёра как энергетического двойника, и будем учиться с ним взаимодействовать. А также Вас ожидают асаны йоги.</p><p></p><p>Чтобы глубже раскрыть тему, и сделать знание живым, этот урок я тоже провёл в формате вебинара.</p><p></p><p>Обязательно выполняйте задания каждого урока, чтобы превращать свободно летающую в пространстве информацию в свой личный опыт и знания.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>С пожеланиями открытий, <br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-02','tantra-mystery',2,2,'Урок 2: Работа с энергетическим двойником','[{"type":"text","markdown":"**СОЗНАНИЕ**\nСегодня мы продолжаем то, что начали на предыдущем уроке, но идём глубже. Если в прошлый раз мы учились ощущать на уровне тела метафору внутреннего мужчины или женщины. То сегодня мы переходим к взаимодействию со своим энергетическим двойником.\n\nОсвоив эти практики вы научитесь самоисцеляться. Но, это побочный эффект. Важный эзотерический закон заключается в том, что внимание необходимо направлять на духовные цели, при этом периферическим зрением наблюдая благотворные изменения на более плотных уровнях реальности. С этой точки зрения важно понимать, что цель данного урока - рост осознанности к энергетическому двойнику, а также повышение тонкости внутренних ощущений."},{"type":"video","vimeoId":"1108026371"},{"type":"text","markdown":"\nЕсли в медитации вы проваливаетесь в сон, попробуйте делать эту \"бабочку\" не лёжа, а сидя. Прислонитесь спиной к дивану, чтобы не уставать. Если же сидя вы не можете расслабиться, то продолжайте делать её лёжа. Нужно найти ту точку на границе сна и бодрствования, когда в мозгу включается альфа- и тета-активность, но еще не отключилась бета. Ней вы видите и осознаете то, что обычно не замечаете. Таким образом, самое главное в этом упражнении - расслабиться и обнаружить то, что происходит в теле на тонком энергетическом уровне. Причём, каким бы ни был ваш текущий уровень осознанности, каждый раз выполняя эту практику, вы можете обнаруживать что-то новое, потому что пределов этой тонкости нет.\n\n**ТЕЛО**\nНа физическом плане к суставной гимнастике и пассивной растяжке добавьте несколько любимых вами асан на растяжку, выполняющихся стоя. Начните с простых асан, направленных на гибкость мышц. Мышцы более податливы, чем связки и сухожилия, и уже через неделю растяжки мышц вы заметите, что тело стало гибче. В каждой асане задерживайтесь на 1-2 минуты с тем, чтобы поглубже в неё войти. Если почувствуете энергетический эффект, замечательно! Если 2 минуты для вас очень много, и тело уже трясется от напряжения (стоячие асаны могут к этому привести), то не печальтесь, выходи из асаны раньше. Минутку передохните в Тадасане, восстановите дыхание, расслабьтесь, прочувствуйте, что происходит в теле, после чего повторите асану ещё раз. Не забывайте, что асана, выполняемая к одной ноге обязательно выполняется и к другой ноге (то есть повтори такую асану по очереди дважды к каждой ноге). Болевой порог не переступайте. Возьмите отношение к себе не как в фитнес-центре, где по 20 асан за занятие делается. А как в догогущем ресторане, где вы на все свои деньги берёте одно блюдо, и наслаждаетесь им во сто крат больше, чем неограниченным шведским столом в фастфуде. Насладитесь и вы этими тремя асанами. Не ограничивайте себя в этом наслаждении. Обратите внимание на дыхание, на ощущения в теле, на эфирные ощущения (перетекание, увеличение объемов), на эмоциональные состояния, на изменение осознанности. Ведь всё это - вы!\n\nЕсли дома есть зеркало, выполните асаны перед ним. Почувствуйте рядом своего энергетического двойника, делающего ту-же асану, что и вы. Посмотрите на него со стороны, силой намерения подправьте его, чтобы асана стала красивей и правильней.\n\nЕсли у вас спортивный характер, вы можете захотеть сделать 10 асан... В таком случае сделайте сколько хотите :)"}]'::jsonb,'00895369-c032-54e4-8212-5f41c5aa9a68') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('53065aac-3b0b-52d2-a5fc-5fb8d9596c67','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 3: Установи контакт с Богом',3,0,'{Тантра} Урок 3 - Установи контакт с Богом','{"ru":"{Тантра} Урок 3 - Установи контакт с Богом"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Привет, {{name}}! Сегодня вас ждёт прекрасный новый день, и ярчайшее событие - третий урок тантры. В нём мы выходим на новый уровень практик.</p><p></p><p>Вопросы, которые мне приходят в письмах и в отчётах по практикам, показывают, что обучение началось на очень глубоком уровне. Это меня радует, но в то-же время и пугает. Хочу обратить ваше внимание на следующее:</p><p></p><p>1. Все развитые религии говорят о том, что любовь и желание блага для всех людей - это та твёрдая почва, которая всегда должна быть у нас под ногами. Если об этом забыть, то можно погрузиться в иллюзию духовного роста, которая ростом отнюдь не является. Даже наоборот - она засосёт как трясина. Поэтому помните, что мы занимаемся духовным развитием, а появляющиеся сиддхи - лишь знаки на пути. Их нужно замечать, и идти дальше.</p><p></p><p>2. Если у вас есть какая-либо форма психопатологии, рекомендую максимально заземляться (гулять на природе, есть мясо, выполнять асаны с прокачкой энергиями нижних чакр...), чтобы ваше духовное путешествие не закончилось в психдиспансере или на приёме у священника-экзорциста. Я серьёзно! Если &quot;голоса&quot; становятся слишком громкими, и вы теряете над ними контроль, прекратите практики как только вы это заметили. Далее в этом курсе будет много простых поведенческих заданий. На них и обратите внимание.</p><p></p><p>3. И напротив - если у вас прагматичный взгляд на мир, то необходимо развивать тонкость и экстрасенсорику. В медитации ловите границу между сном и явью, и, удерживая осознанность, поглубже заныривайте в изучение двойника, а также тем ближайших уроков, так как в них содержится богатейшая почва для самопознания.</p><p></p><p>Как я говорил во вводном уроке, тантра - это баланс над пропастью! Удерживайте его!</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Желаю вам космического дня, <br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Привет, {{name}}! Сегодня вас ждёт прекрасный новый день, и ярчайшее событие - третий урок тантры. В нём мы выходим на новый уровень практик.</p><p></p><p>Вопросы, которые мне приходят в письмах и в отчётах по практикам, показывают, что обучение началось на очень глубоком уровне. Это меня радует, но в то-же время и пугает. Хочу обратить ваше внимание на следующее:</p><p></p><p>1. Все развитые религии говорят о том, что любовь и желание блага для всех людей - это та твёрдая почва, которая всегда должна быть у нас под ногами. Если об этом забыть, то можно погрузиться в иллюзию духовного роста, которая ростом отнюдь не является. Даже наоборот - она засосёт как трясина. Поэтому помните, что мы занимаемся духовным развитием, а появляющиеся сиддхи - лишь знаки на пути. Их нужно замечать, и идти дальше.</p><p></p><p>2. Если у вас есть какая-либо форма психопатологии, рекомендую максимально заземляться (гулять на природе, есть мясо, выполнять асаны с прокачкой энергиями нижних чакр...), чтобы ваше духовное путешествие не закончилось в психдиспансере или на приёме у священника-экзорциста. Я серьёзно! Если &quot;голоса&quot; становятся слишком громкими, и вы теряете над ними контроль, прекратите практики как только вы это заметили. Далее в этом курсе будет много простых поведенческих заданий. На них и обратите внимание.</p><p></p><p>3. И напротив - если у вас прагматичный взгляд на мир, то необходимо развивать тонкость и экстрасенсорику. В медитации ловите границу между сном и явью, и, удерживая осознанность, поглубже заныривайте в изучение двойника, а также тем ближайших уроков, так как в них содержится богатейшая почва для самопознания.</p><p></p><p>Как я говорил во вводном уроке, тантра - это баланс над пропастью! Удерживайте его!</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Желаю вам космического дня, <br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-03-text","type":"text","html":"<p>Привет, {{name}}! Сегодня вас ждёт прекрасный новый день, и ярчайшее событие - третий урок тантры. В нём мы выходим на новый уровень практик.</p><p></p><p>Вопросы, которые мне приходят в письмах и в отчётах по практикам, показывают, что обучение началось на очень глубоком уровне. Это меня радует, но в то-же время и пугает. Хочу обратить ваше внимание на следующее:</p><p></p><p>1. Все развитые религии говорят о том, что любовь и желание блага для всех людей - это та твёрдая почва, которая всегда должна быть у нас под ногами. Если об этом забыть, то можно погрузиться в иллюзию духовного роста, которая ростом отнюдь не является. Даже наоборот - она засосёт как трясина. Поэтому помните, что мы занимаемся духовным развитием, а появляющиеся сиддхи - лишь знаки на пути. Их нужно замечать, и идти дальше.</p><p></p><p>2. Если у вас есть какая-либо форма психопатологии, рекомендую максимально заземляться (гулять на природе, есть мясо, выполнять асаны с прокачкой энергиями нижних чакр...), чтобы ваше духовное путешествие не закончилось в психдиспансере или на приёме у священника-экзорциста. Я серьёзно! Если &quot;голоса&quot; становятся слишком громкими, и вы теряете над ними контроль, прекратите практики как только вы это заметили. Далее в этом курсе будет много простых поведенческих заданий. На них и обратите внимание.</p><p></p><p>3. И напротив - если у вас прагматичный взгляд на мир, то необходимо развивать тонкость и экстрасенсорику. В медитации ловите границу между сном и явью, и, удерживая осознанность, поглубже заныривайте в изучение двойника, а также тем ближайших уроков, так как в них содержится богатейшая почва для самопознания.</p><p></p><p>Как я говорил во вводном уроке, тантра - это баланс над пропастью! Удерживайте его!</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Желаю вам космического дня, <br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-03','tantra-mystery',3,2,'Урок 3: Установи контакт с Богом','[{"type":"text","markdown":"**СОЗНАНИЕ**\nРакета готова к старту! Усаживайся в командирское кресло, и пристегни ремни покрепче. Сегодня мы выходим на более высокий уровень энергетики и духовности. Посмотри этой видео, и осваивай новое состояние."},{"type":"video","vimeoId":"434646533"},{"type":"text","markdown":"\n\n**ТЕЛО**\nНа физическом плане продолжай суставную гимнастику и пассивную растяжку, а также выполни три асаны на растяжку в положении сидя. Отнесись к выбору и выпонению этих асан также, как в предыдущем уроке. Выбери асаны на растягивание трёх разных групп мышц таза и бёдер - передних (распрямляющих), задних (сгибающих) и внутренних (приводящих), и повтори каждую асану дважды. Однако, так как это асаны сидя, они более реллаксирующие, и их можно выполнять чуточку дольше. Поэтому у тебя увеличивается шанс ощутить тот эффект, который наступает при длительном выполнении асаны. Почувствуй, что происходит в твоём теле и в твоём внутреннем мире. Закрой глаза. Возможно, ты увидишь какие-то образы. А может быть услышишь волны звука. Или почувствуешь движение чего-то внутри тебя. Следуй за тем, что происходит, пока это ощущение не покинет тебя. Далее подожди, и ты заметишь приход чего-то нового. Так может произойти несколько раз. Когда же что-либо происходить перестанет, это признак того, что асана дала тебе всё, что могла (здесь и сейчас). Выходи из неё... Но не спеши! Ты пропустишь послевкусие :))) Вход и выход из асаны тоже важны. Наблюдай перераспределение энергии и возникающие состояния. Затем выполни минутную шавасану. Вот тут тебя тоже ждёт фонтан ощущений. И только когда он успокоится, переходи к следующей асане.\n\n**ВЕБИНАР**\nПредлагаю Вам посмотреть запись вебинара, который прошёл после трёх первых уроков данного курса. Он был посвящён ответам на возникшие вопросы."},{"type":"video","vimeoId":"1249122843"}]'::jsonb,'53065aac-3b0b-52d2-a5fc-5fb8d9596c67') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('7b98c220-e8b1-5134-85f9-c5d4d79e63dc','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 4: Почувствуй себя Богом',4,0,'{Тантра} Урок 4 - Почувствуй себя Богом','{"ru":"{Тантра} Урок 4 - Почувствуй себя Богом"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня вас ожидает сюрприз! И хотя вы могли подозревать что-то подобное, всё-равно вам будет приятно :)</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Успешной практики!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня вас ожидает сюрприз! И хотя вы могли подозревать что-то подобное, всё-равно вам будет приятно :)</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Успешной практики!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня вас ожидает сюрприз! И хотя вы могли подозревать что-то подобное, всё-равно вам будет приятно :)</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Успешной практики!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-04','tantra-mystery',4,3,'Урок 4: Почувствуй себя Богом','[{"type":"text","markdown":"**СОЗНАНИЕ**\nСегодня летим ещё выше. Вопрос - КТО вчера выполнял тантрическую практику с Божеством? Конечно-же другое Божество! И это - ты! Данное утверждение звучит странно, но если эту точку зрения ты примешь и осознаешь, то перед тобой откроются интереснейшие возможности. Ты поймёшь, что ты и есть «Альфа и Омега. Начало и Конец». Ты возьмёшь на себя ответственность за всё, что с тобой якобы «происходит». Прекратишь многие энергетические оттоки, и начнёшь творить свой новый мир… Посмотри этой видео. Я надеюсь, оно поможет тебе освоить состояние Божества."},{"type":"video","vimeoId":"266398916"},{"type":"text","markdown":"\n\n**ТЕЛО**\nНа физическом плане продолжай суставную гимнастику и упражнения пассивной растяжки, а также выполни три асаны на растяжку в положении лёжа. Снова выбери асаны, которые растягивают три разные группы мышц, и повтори каждую асану дважды."}]'::jsonb,'7b98c220-e8b1-5134-85f9-c5d4d79e63dc') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('c1f641c9-18a7-53ff-96fc-e61c00183167','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 5: Увидь Богов вокруг себя',5,0,'{Тантра} Урок 5 - Увидь Богов вокруг себя','{"ru":"{Тантра} Урок 5 - Увидь Богов вокруг себя"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Привет, {{name}}! Сегодня мы продолжаем осваиваться в мире Богов, и вас ждёт необычное задание.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Божественного дня,<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Привет, {{name}}! Сегодня мы продолжаем осваиваться в мире Богов, и вас ждёт необычное задание.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Божественного дня,<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-05-text","type":"text","html":"<p>Привет, {{name}}! Сегодня мы продолжаем осваиваться в мире Богов, и вас ждёт необычное задание.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Божественного дня,<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-05','tantra-mystery',5,2,'Урок 5: Увидь Богов вокруг себя','[{"type":"text","markdown":"**СОЗНАНИЕ**\nСегодня мы начинаем спускаться с небес на землю. Но не резко, а удерживая полученные состояния. Если тебе удались задания двух предыдущих уроков, то данный урок тебе несомненно понравится. Ты наконец сделаешь первый шаг в окружающий мир в своём новом качестве."},{"type":"video","vimeoId":"266399073"},{"type":"text","markdown":"\n\n**ТЕЛО**\nВ плане работы с телом продолжай делать суставную гимнастику и пассивную растяжку. А также выбери и выполни три новые асаны стоя (не те, которые были выбраны на Уроке 2). Заодно ответь себе на вопрос - что в этих асанах отличается от предыдущих, то есть из-за чего в предыдущий раз предпочтение было отдано не им? Это очень интересная тема... В предыдущий раз я предлагал тебе сделать выбор, слушая собственное желание и голос тела. А когда мы действуем таким образом, мы выбираем \"любимые\" асаны - то есть асаны, которые нашему телу и психике по каким-то причинам УДОБНЫ, которые усиливают наши и без того сильные качества. Кастанеда писал, что путь мага - это Путь война. И я пониманю, что этот курс проходят те, кому уже надоело играть с собой в игры. Тем не менее, мы часто ищем какой-то Великой премудрости, забывая что каждый наш шаг - это не только путь, но и учитель. И выбор асан для практики - не исключение. На всё необходимо обращать внимание, и обнаруживать ключики к себе. Если же мы заходим с другой стороны, и начинаем выполнять асаны, которые не хочется выполнять, мы чётко выходим из зоны комфорта, и начинаем прорабатывать свои слабые стороны и осваивать новые состояния.\n\nТут ты можешь сказать - \"вот уж не про меня, я всегда выбираю то, что сложно, и что для меня полезно\". Если так, то обрати внимание на этот факт, и сейчас сделай наоборот - выбери то, что \"просто\" и \"бесполезно\". Обрати внимание на внутренние переживания при выполнении того что не является сложным. Чувство бессмысленности, бездарщины, деградации... Что ещё? Что скрывают эти состояния? Какие убеждения, программы поведения... Что конструктивное и гармоничное находится за ними, на другой стороне? Вот тут закопан твой клад :)...\n\nИ ещё подсказка - что бы ты ни почувствовал, это всего-лишь состояние. И с ним можно работать уже знакомыми нам методами тантры. Я сказал с \"ним\"... а может быть это не \"он\", а \"она\"? :))) Русский язык мочуч ещё и тем, что даёт половую принадлежность даже нашим состояниям и эмоциям. А значит с ними можно выполнять тантрическую практику. Почувствовать сексуальное желание, направить энергию, принять ответ, замкнуть энергию в круг, раствориться, интегрироваться... Как только это произойдёт, ты откроешь в себе что-то новое - то, до чего сложно дойти ментальным анализом. Конечно, эта практика не для всех. Но, если ты в состоянии разотождествиться, отделить себя от этого состояния (т.е. можешь наблюдать его уже без эмоций), и чувствуешь внутреннюю уверенность, попробуй выполнить данную практику. Тебе поможет метафора злобных божеств. На тибетских танках часто встречаются изображения злобных божеств в позе яб-юм. И многие практики выполняются именно в этом состоянии. Но ВНИМАНИЕ - разотождествление и осозанность критически важны для такой практики!!!!! Если они теряются, ты будешь создавать себе препятствия на пути развития."}]'::jsonb,'c1f641c9-18a7-53ff-96fc-e61c00183167') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('52598c9a-1a92-5a60-bc0a-8ce5b02c6bda','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 6: Почувствуй главное в людях',6,0,'{Тантра} Урок 6 - Почувствуй главное в людях','{"ru":"{Тантра} Урок 6 - Почувствуй главное в людях"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Привет, {{name}}! Сегодня поворотный шаг курса. Мы спускаемся с неба на землю, и плавно переходим к практическому использованию в нашей жизни тех состояний, которые мы так хорошо исследовали в предыдущих уроках. Ведь ты хочешь начать делать свою жизнь лучше? И не когда-нибудь, а прямо сегодня? Тогда вперёд! :)</p><p></p><p>Нажмите кнопку ниже, чтобы открыть шестой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Улыбок и любви!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Привет, {{name}}! Сегодня поворотный шаг курса. Мы спускаемся с неба на землю, и плавно переходим к практическому использованию в нашей жизни тех состояний, которые мы так хорошо исследовали в предыдущих уроках. Ведь ты хочешь начать делать свою жизнь лучше? И не когда-нибудь, а прямо сегодня? Тогда вперёд! :)</p><p></p><p>Нажмите кнопку ниже, чтобы открыть шестой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Улыбок и любви!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-06-text","type":"text","html":"<p>Привет, {{name}}! Сегодня поворотный шаг курса. Мы спускаемся с неба на землю, и плавно переходим к практическому использованию в нашей жизни тех состояний, которые мы так хорошо исследовали в предыдущих уроках. Ведь ты хочешь начать делать свою жизнь лучше? И не когда-нибудь, а прямо сегодня? Тогда вперёд! :)</p><p></p><p>Нажмите кнопку ниже, чтобы открыть шестой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Улыбок и любви!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-06','tantra-mystery',6,2,'Урок 6: Почувствуй главное в людях','[{"type":"text","markdown":"**СОЗНАНИЕ**\nВ этом и в нескольких следующих уроках мы будем учиться удерживать божественное состояние, а также использовать тонкость, наработанную при взаимодействии с внутренним партнёром, для того, чтобы делать нашу реальную жизнь лучше. Плоды этих уроков должны проявляться сразу, прямо в процессе выполнения практик. Таким образом с каждым днём твоя жизнь будет становиться лучше. Посмотри видео, и выполни описанное в нём упражнение. В комментариях к уроку опиши как эта практика повлияла на твои отношения с людьми."},{"type":"video","vimeoId":"266399226"},{"type":"text","markdown":"\n\n**ТЕЛО**\nВ результате неспешного, вдумчивого выполнения асан, как я рекомендовал в предыдущих уроках, я надеюсь, тебе удалось почувствовать что такое АСАНА. Какой энергетический эффект она несёт, как меняется твое состояние в результате её выполнения. Сегодня мы будем учиться удерживать этот подход к асанам при выполнении комплекса Сурья Намаскар. Это эффективнейший комплекс асан, и я предлагаю тебе его освоить. Но перед этим не забудь выполнить суставную гимнастику. Она не только полезна, но также помогает переключить внимание на внутренние процессы. Ниже я вставил два видео, в которых я показываю Сурья Намаскар, чтобы у тебя сложилось более полное его восприятие."},{"type":"video","vimeoId":"1249151142"},{"type":"video","vimeoId":"1249151168"},{"type":"text","markdown":"\nКогда на физическом уровне техника Сурья Намаскар освоена, обрати внимание на энергетические процессы, происходящие в процессе выполнения асан. Предлагаю тебе посмотреть урок из курса \"Магия йоги\", чтобы освоить техники прокачки во время выполнения асан. И мега-важное дополнение к этому уроку. Так как мы занимаемся тантрой, и тебе знаком твой энергетический двойник, обязательно прокачивай двойника, а не только собственное тело! Если выполнение асан с прокачкой поднимет тебя в небо, то прокачка двойника, отправит прямиком в космос :)"},{"type":"video","vimeoId":"1249149595"}]'::jsonb,'52598c9a-1a92-5a60-bc0a-8ce5b02c6bda') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('04ae4e19-3cbc-5abb-8c0e-6712de7836ba','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 7: Учись погружаться в человека',7,0,'{Тантра} Урок 7 - Учись погружаться в человека','{"ru":"{Тантра} Урок 7 - Учись погружаться в человека"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}! Я надеюсь, вчера тебе удалось ощутить насколько эффективны бывают простые на первый взгляд практики. Сегодня мы ещё глубже погружаемся в мир людей мир, и тебя ожидает новая практика - более близкий контакт с близким человеком :) Ты заметишь интересный эффект - хотя это эзотерическая практика, о выполнении которой знаешь только ты, она чудесным образом влияет на отношения. И, если практиковать её некоторое время, то непременно улучшится взаимопонимание, и ваши отношения станут более искренними и глубокими.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть седьмой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>С пожеланиями открытий,<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}! Я надеюсь, вчера тебе удалось ощутить насколько эффективны бывают простые на первый взгляд практики. Сегодня мы ещё глубже погружаемся в мир людей мир, и тебя ожидает новая практика - более близкий контакт с близким человеком :) Ты заметишь интересный эффект - хотя это эзотерическая практика, о выполнении которой знаешь только ты, она чудесным образом влияет на отношения. И, если практиковать её некоторое время, то непременно улучшится взаимопонимание, и ваши отношения станут более искренними и глубокими.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть седьмой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>С пожеланиями открытий,<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-07-text","type":"text","html":"<p>Здравствуйте, {{name}}! Я надеюсь, вчера тебе удалось ощутить насколько эффективны бывают простые на первый взгляд практики. Сегодня мы ещё глубже погружаемся в мир людей мир, и тебя ожидает новая практика - более близкий контакт с близким человеком :) Ты заметишь интересный эффект - хотя это эзотерическая практика, о выполнении которой знаешь только ты, она чудесным образом влияет на отношения. И, если практиковать её некоторое время, то непременно улучшится взаимопонимание, и ваши отношения станут более искренними и глубокими.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть седьмой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>С пожеланиями открытий,<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-07','tantra-mystery',7,3,'Урок 7: Учись погружаться в человека','[{"type":"text","markdown":"**СОЗНАНИЕ**\nКаждый из нас много раз засыпал с любимым человеком. Вспомни, как ярко это происходило вначале. Выброс гормонов наполнял тебя всеми цветами радуги. Со временем гормональные всплески успокоились, и опыт совместного засыпания превратился во что-то обыденное. Как же много мы при этом упускаем! Спад гормонального шторма открывает врата мудрости. Но мы становимся не мудрыми, а просто сонными. Сегодня вечером попробуй не уснуть, а войти в дверь, которая открывается когда ты обнимаешь любимого человека и расслабляешься. Это захватывающее путешествие. Причем, каждый вечер оно разное. Посмотри видео, выполни практику, и опиши в комментариях свой внутренний опыт."},{"type":"video","vimeoId":"268307760"},{"type":"text","markdown":"\n\n**ТЕЛО**\nНа физическом плане продолжаем осваивать осознанность в динамике, выполняя Сурья Намаскар. Если вчера состоялось первое знакомство, то сегодня этот комплекс уже будет получаться заметно лучше, возможно даже на автомате, и ты заметишь его энергетические эффекты. Сначала выполни его в произвольном темпе один раз к каждой ноге (т.е. всего два цикла асан), а затем ещё два раза к каждой ноге, синхронизируясь с дыханием.  Не забудь предварительно выполнить суставную гимнастику и вращения тазом."}]'::jsonb,'04ae4e19-3cbc-5abb-8c0e-6712de7836ba') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('ea33da47-0244-58b8-bb69-e1c366f0a970','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 8: Почувствуй собеседника',8,0,'{Тантра} Урок 8 - Почувствуй собеседника','{"ru":"{Тантра} Урок 8 - Почувствуй собеседника"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Привет, {{name}}!</p><p></p><p>Просыпайся! Тантра ждёт тебя! :) Сегодняшняя практика принесет тебе реальные, ощутимые, значимые (нужное подчеркни) выгоды. Посмотри урок утром, так как выполнять эту практику нужно будет в течение дня.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть восьмой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>С пожеланиями открытий,<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Привет, {{name}}!</p><p></p><p>Просыпайся! Тантра ждёт тебя! :) Сегодняшняя практика принесет тебе реальные, ощутимые, значимые (нужное подчеркни) выгоды. Посмотри урок утром, так как выполнять эту практику нужно будет в течение дня.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть восьмой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>С пожеланиями открытий,<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-08-text","type":"text","html":"<p>Привет, {{name}}!</p><p></p><p>Просыпайся! Тантра ждёт тебя! :) Сегодняшняя практика принесет тебе реальные, ощутимые, значимые (нужное подчеркни) выгоды. Посмотри урок утром, так как выполнять эту практику нужно будет в течение дня.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть восьмой урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>С пожеланиями открытий,<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-08','tantra-mystery',8,2,'Урок 8: Почувствуй собеседника','[{"type":"text","markdown":"**СОЗНАНИЕ**\nСегодняшняя практика поможет тебе перенести навык, полученный в предыдущем уроке, из кровати в окружающий мир - на работу, на встречу с друзьями и т.д. Освоив её ты по-другому увидишь других людей. Сотрутся эмоциональные барьеры, улучшатся отношения с коллегами и клиентами, ты станешь убедительней, и в то-же время чутче."},{"type":"video","vimeoId":"268307913"},{"type":"text","markdown":"\n\n**ТЕЛО**\nС начала этого курса ты ежедневно выполняешь асаны (надеюсь на это). И я предлагаю выходной. Как обычно сделай суставную гимнастику... А затем вместо асан выполни динамический комплекс упражнений для мышц тазового дна:"},{"type":"video","vimeoId":"1249122841"}]'::jsonb,'ea33da47-0244-58b8-bb69-e1c366f0a970') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('2786e399-8a4e-5070-8da7-772bc439c914','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 9: Следуй за сексуальными импульсами',9,0,'{Тантра} Урок 9 - Следуй за сексуальными импульсами','{"ru":"{Тантра} Урок 9 - Следуй за сексуальными импульсами"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}! </p><p></p><p>Сегодня тебя снова ждёт практика, которая выполняется не на йоговском коврике, а в социальном взаимодействии. Поэтому посмотри этот урок утром, чтобы у тебя было побольше времени для выполнения практики.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть девятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Успехов и улыбок,<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}! </p><p></p><p>Сегодня тебя снова ждёт практика, которая выполняется не на йоговском коврике, а в социальном взаимодействии. Поэтому посмотри этот урок утром, чтобы у тебя было побольше времени для выполнения практики.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть девятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Успехов и улыбок,<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-09-text","type":"text","html":"<p>Здравствуйте, {{name}}! </p><p></p><p>Сегодня тебя снова ждёт практика, которая выполняется не на йоговском коврике, а в социальном взаимодействии. Поэтому посмотри этот урок утром, чтобы у тебя было побольше времени для выполнения практики.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть девятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Успехов и улыбок,<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-09','tantra-mystery',9,2,'Урок 9: Следуй за сексуальными импульсами','[{"type":"text","markdown":"СОЗНАНИЕ\n\nСегодня мы опускаемся на ещё более \"примитивный\" уровень социального взаимодействия. Примитивным я его назвал только лишь потому что это то, что умеют маленькие дети, и вроде как в этом нет высоты, эстетики, изящества, проявления талантов... и других качеств, которые мы так ценим в себе и в окружающих. Мы будем учиться решать две простые задачи: слышать свои желания и следовать за ними. Странно, но и то и другое для нас не просто. Потому что именно в этом проявляется жестокая уловка цивилизационных сценариев, которые кормятся нашими невротичными энергиями. Ведь когда желание (то есть энергия) не реализуется гармонично, оно накапливается, и реализуется в виде конфликтов, неврозов, болезней, и так далее в зависимости от возраста. Так вот - у нас в голове есть множество убеждений и стереотипов, препятствующих выполнению желаний, особенно желаний, связанных с удовольствиями (делу время, потехе час, не прелюбодействуй и т.п.), плюс рационализации, всевозможные страхи... В связи с этим мы стали глухими к своему внутреннему голосу. Ведь проще не слышать, чем каждый раз бить себя по рукам. У нас на курсе нет времени для того, чтобы разглюкивать каждый отдельно взятый заглюк. Это тема для многолетних психологических тренингов. Но я специально даю тебе поведенческую практику, которая мощно пробуждает энергию. Если ты её выполнишь, и войдешь во вкус, то будешь выполнять её в дальнейшем. И тогда высвободившаяся энергия попросту выжжет все заглюки скопом, и тебе приоткроется дверца в то состояние, которое было у тебя в далёком детстве - когда ещё можно было следовать за своими желаниями."},{"type":"video","vimeoId":"267891626"},{"type":"text","markdown":"\n\n**ТЕЛО**\nПредлагаю тебе выполнить комплекс асан с прокачкой. Ниже находится видео, в котором я демонстрирую данную технику. Освой её, и в будущем ты сможешь использовать эту технику при выполнении других комплексов. Даже занимаясь в группе в фитнес-центре, ты сможешь существенно усилить практику, и получить лучший результат. И хотя в этом видео я ничего не говорю о двойнике, не забудь - прокачивай не только собственное тело, но и двойника."},{"type":"video","vimeoId":"1249122937"}]'::jsonb,'2786e399-8a4e-5070-8da7-772bc439c914') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('5f76e217-af92-54ad-baa4-38c4d0e0d685','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 10: Найди тантрического партнёра',10,0,'{Тантра} Урок 10 - Найди тантрического партнёра','{"ru":"{Тантра} Урок 10 - Найди тантрического партнёра"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Привет, {{name}}!</p><p></p><p>Сегодня мы немного приблизимся к тому, что в обиходе считается тантрой. Кому-то этот шаг дастся очень легко, тогда как кому-то сложно. Тем не менее, это всего-лишь один шаг.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть десятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Творческого дня,<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Привет, {{name}}!</p><p></p><p>Сегодня мы немного приблизимся к тому, что в обиходе считается тантрой. Кому-то этот шаг дастся очень легко, тогда как кому-то сложно. Тем не менее, это всего-лишь один шаг.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть десятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Творческого дня,<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-10-text","type":"text","html":"<p>Привет, {{name}}!</p><p></p><p>Сегодня мы немного приблизимся к тому, что в обиходе считается тантрой. Кому-то этот шаг дастся очень легко, тогда как кому-то сложно. Тем не менее, это всего-лишь один шаг.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть десятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Творческого дня,<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-10','tantra-mystery',10,3,'Урок 10: Найди тантрического партнёра','[{"type":"text","markdown":"**СОЗНАНИЕ**\nЕсли погуглить картинки по слову \"Тантра\", то на 90% изображений будут изображены мужчина и женщина в какой-либо сексуальной позе. И это не лишено оснований. Занимаясь сексом мы часто настолько сфокусированы на самом сексе, что кроме него ничего и не замечаем. Тантра же предлагает перейти во внутренний мир, и рассматривать секс как основу для различных психопрактик. Дело в том, что во время занятий сексом вы открываетесь, и выделяется столько энергии, что происходят инсайты, которые в обычном состоянии сознания труднодостижимы. Этот курс не про секс, но давай взглянем на то, что же из себя представляют тантрические парные практики. Для этого тебе понадобится партнёр. И задача сегодняшнего дня - найти и подготовить его."},{"type":"video","vimeoId":"268308002"},{"type":"text","markdown":"\n\n**ТЕЛО**\nНа уровне тела продолжай выполнять суставную гимнастику и упражнения пассивной растяжки. А также сегодня выполни комплекс Сурья Намаскар. При этом прокачивай себя и двойника той энергией, которая тебе необходима. Творчески используй ключи, продемонстрированные мной в предыдущем уроке."}]'::jsonb,'5f76e217-af92-54ad-baa4-38c4d0e0d685') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('d8fc166d-1a7b-5bd2-b817-76e84b7c6e95','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 11: Тантрическая практика с партнёром',11,0,'{Тантра} Урок 11 - Тантрическая практика с партнёром','{"ru":"{Тантра} Урок 11 - Тантрическая практика с партнёром"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Привет, {{name}}!</p><p></p><p>ТАДАММММ!!! Сегодня день парной практики! Посмотри видео о том, как она выполняется. Если же у тебя не с кем выполнить эту практику, не растраивайся! Для тебя я подготовил дополнительное видео :)</p><p></p><p>Нажмите кнопку ниже, чтобы открыть одиннадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Плодотворной практики,<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Привет, {{name}}!</p><p></p><p>ТАДАММММ!!! Сегодня день парной практики! Посмотри видео о том, как она выполняется. Если же у тебя не с кем выполнить эту практику, не растраивайся! Для тебя я подготовил дополнительное видео :)</p><p></p><p>Нажмите кнопку ниже, чтобы открыть одиннадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Плодотворной практики,<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-11-text","type":"text","html":"<p>Привет, {{name}}!</p><p></p><p>ТАДАММММ!!! Сегодня день парной практики! Посмотри видео о том, как она выполняется. Если же у тебя не с кем выполнить эту практику, не растраивайся! Для тебя я подготовил дополнительное видео :)</p><p></p><p>Нажмите кнопку ниже, чтобы открыть одиннадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Плодотворной практики,<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-11','tantra-mystery',11,2,'Урок 11: Тантрическая практика с партнёром','[{"type":"text","markdown":"**СОЗНАНИЕ**\nСегодня тебя ожидает интереснейшее приключение. Первый опыт традиционной тантрической практики. Она глубоко эзотерична. То есть то, что происходит на самом деле, сильно отличается от того, как это выглядит со стороны. Это не просто обнимашки. И в этом видео я передаю ключи, которые необходимы, чтобы открыть дверь в тантрическое пространство.\n\nЯ понимаю, что одного дня тебе могло не хватить для поиска партнёра. Если так и есть, всё-равно посмотри это видео, чтобы узнать как эта практика выполняется, и выполнить её, когда партнёр у тебя появится."},{"type":"video","vimeoId":"268308080"},{"type":"text","markdown":"\nЕСЛИ ПАРТНЁРА НЕТ...\n\nЕсли партнёра для парной практики у тебя нет, не расстраивайся. Поверь, что в данный момент для тебя так лучше. Посмотри следующее видео, и выполни особенную практику, которую я в нём даю. Эта практика применима в самых разных контекстах -  как при поиске партнёра, так и при работе над собой."},{"type":"video","vimeoId":"268309486"},{"type":"text","markdown":"\n\n**ТЕЛО**\nНа физическом уровне продолжай выполнять суставную гимнастику, а также упражнения пассивной растяжки. Если есть энтузиазм, то также выполни комплекс Сурья Намаскар. Не забудь покачиваться."}]'::jsonb,'d8fc166d-1a7b-5bd2-b817-76e84b7c6e95') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('3225c315-b30a-5a43-9b0b-f5d23fee2ba4','22445b31-b0b5-5beb-9bd7-1916852d47e4','Урок 12: Увидь тантру во всём',12,0,'{Тантра} Урок 12 - Увидь тантру во всём','{"ru":"{Тантра} Урок 12 - Увидь тантру во всём"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg" alt="Тантра - мистерия взаимоотношений" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Привет, {{name}}! </p><p></p><p>Время пролетело незаметно, и сегодня тебя ждёт заключительный урок курса. Что-ж поделать... Всё, что имеет начало, имеет и конец. На этом шаге наша задача - зафиксировать результат, и наметить следующие шаги.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть двенадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Если вы прошли все уроки и выполняли практики, я уверен, что вы получили ощутимые результаты. Возможно, сейчас вы наполнены энтузиазмом двигаться дальше, и исследовать другие направления. В этом случае имейте в виду, что я подготовил всесторонний комплект практикумов и курсов, которые могут быть вам полезны. Чтобы выбрать то, что вам подойдёт, сначала вам нужно определиться с направлением - то есть честно осознать какая сфера жизни (или ситуации) сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем решить сколько времени вы готовы посвятить урокам и практикам. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать: </p><p></p><p>ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href="https://zamkovoi.yoga/m1">https://zamkovoi.yoga/m1</a><br>- Месяц наслаждений: <a href="https://zamkovoi.yoga/m2">https://zamkovoi.yoga/m2</a><br>- Месяц силы: <a href="https://zamkovoi.yoga/m3">https://zamkovoi.yoga/m3</a><br>- Месяц любви: <a href="https://zamkovoi.yoga/m4">https://zamkovoi.yoga/m4</a><br>- Месяц свободы: <a href="https://zamkovoi.yoga/m5">https://zamkovoi.yoga/m5</a><br>- Месяц мудрости: <a href="https://zamkovoi.yoga/m6">https://zamkovoi.yoga/m6</a><br>- Месяц святости: <a href="https://zamkovoi.yoga/m7">https://zamkovoi.yoga/m7</a></p><p></p><p>КУРСЫ:<br>- Йога и здоровье: <a href="https://zamkovoi.yoga/yoga1">https://zamkovoi.yoga/yoga1</a><br>- Йога плюс женственность: <a href="https://zamkovoi.yoga/yoga2">https://zamkovoi.yoga/yoga2</a><br>- Осуществи мечту: <a href="https://zamkovoi.yoga/yoga3">https://zamkovoi.yoga/yoga3</a><br>- Планета любви: <a href="https://zamkovoi.yoga/yoga4">https://zamkovoi.yoga/yoga4</a><br>- Источник творческой силы: <a href="https://zamkovoi.yoga/yoga5">https://zamkovoi.yoga/yoga5</a><br>- 36 шагов йоги: <a href="https://zamkovoi.yoga/yoga36">https://zamkovoi.yoga/yoga36</a><br>- Путь души: <a href="https://zamkovoi.yoga/yogas">https://zamkovoi.yoga/yogas</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg\" alt=\"Тантра - мистерия взаимоотношений\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Привет, {{name}}! </p><p></p><p>Время пролетело незаметно, и сегодня тебя ждёт заключительный урок курса. Что-ж поделать... Всё, что имеет начало, имеет и конец. На этом шаге наша задача - зафиксировать результат, и наметить следующие шаги.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть двенадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Если вы прошли все уроки и выполняли практики, я уверен, что вы получили ощутимые результаты. Возможно, сейчас вы наполнены энтузиазмом двигаться дальше, и исследовать другие направления. В этом случае имейте в виду, что я подготовил всесторонний комплект практикумов и курсов, которые могут быть вам полезны. Чтобы выбрать то, что вам подойдёт, сначала вам нужно определиться с направлением - то есть честно осознать какая сфера жизни (или ситуации) сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем решить сколько времени вы готовы посвятить урокам и практикам. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать: </p><p></p><p>ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br>- Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br>- Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br>- Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br>- Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br>- Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br>- Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a></p><p></p><p>КУРСЫ:<br>- Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br>- Йога плюс женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br>- Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br>- Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br>- Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br>- 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br>- Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-tantra-mystery-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/tantra-mystery/tantra-mystery_email-e757bc5b6506.jpg","alt":"Тантра - мистерия взаимоотношений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":1000,"naturalHeight":371},{"id":"tantra-mystery-12-text","type":"text","html":"<p>Привет, {{name}}! </p><p></p><p>Время пролетело незаметно, и сегодня тебя ждёт заключительный урок курса. Что-ж поделать... Всё, что имеет начало, имеет и конец. На этом шаге наша задача - зафиксировать результат, и наметить следующие шаги.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть двенадцатый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Если вы прошли все уроки и выполняли практики, я уверен, что вы получили ощутимые результаты. Возможно, сейчас вы наполнены энтузиазмом двигаться дальше, и исследовать другие направления. В этом случае имейте в виду, что я подготовил всесторонний комплект практикумов и курсов, которые могут быть вам полезны. Чтобы выбрать то, что вам подойдёт, сначала вам нужно определиться с направлением - то есть честно осознать какая сфера жизни (или ситуации) сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем решить сколько времени вы готовы посвятить урокам и практикам. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать: </p><p></p><p>ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br>- Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br>- Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br>- Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br>- Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br>- Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br>- Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a></p><p></p><p>КУРСЫ:<br>- Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br>- Йога плюс женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br>- Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br>- Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br>- Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br>- 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br>- Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('tantra-mystery-12','tantra-mystery',12,2,'Урок 12: Увидь тантру во всём','[{"type":"text","markdown":"**СОЗНАНИЕ**\nСегодня мы делаем завершающий шаг курса, но, я надеюсь, не завершающий шаг твоего путешествия в тантру. Мы прошли длинный путь. Попробуй вспомнить первый шаг... Кажется, что он был очень давно. Это говорит о том, что за прошедшее время в тебе многое изменилось. А это значит, что теперь ты чуточку другой человек. И сейчас обязательно необходимо зафиксировать результат, а также наметить будущие шаги. Если это не сделать, старые формы мышления и поведения будут затягивать тебя обратно. Поэтому перечитай свой дневник, в котором я надеюсь перечислено много инсайтов. Допиши что ещё было важного. Это тот-же приём, который мы делали после каждой практики. Который помогал якориться и фиксировать плоды эзотерических усилий в реальном мире. А также посмотри это видео. Оно поможет тебе понять какие дальнейшие шаги в тантре ты можешь делать в ближайшее время. Дорогу осилит идущий. Когда ты выполнить эти практики, тебе откроются следующие. А вообще, далеко не загадывай. Оставь себе свободу :)"},{"type":"video","vimeoId":"268308181"},{"type":"text","markdown":"\n\n**ТЕЛО**\nНа уровне тела выполни суставную гимнастику, после творчески выполни комплекс из произвольной последовательности асан. Почувствуй поток, который ведёт твоё тело, и следуй в нём. Сформируй намерение, поставь поток, выполни все асаны с прокачкой себя и двойника, посвяти заслуги, и отпусти поток. Рассматривай это, как выпускной экзамен! Сравни с эффективностью практики йоги до начала прохождения данного курса. Поблагодари себя, и всех, кто тебе помогал на пути."}]'::jsonb,'3225c315-b30a-5a43-9b0b-f5d23fee2ba4') on conflict(id) do nothing;
